<script setup>
import {useCart} from '../stores/cart.js';import {useAuth} from '../stores/auth.js';import {useOrders} from '../stores/orders.js';import {useRouter} from 'vue-router';import {money,useTask} from '../composables/useTask.js'
const cart=useCart(),auth=useAuth(),orders=useOrders(),router=useRouter();const {busy,error,run}=useTask();function place(){if(!auth.me){router.push('/account');return}run(async()=>{await orders.place(cart.items);cart.clear();await router.push('/orders')})}
</script><template><h2>Your cart</h2><p v-if="error" role="alert">{{error}}</p><div v-if="cart.count" class="panel"><div v-for="f in cart.items" :key="f.id" class="line"><b>{{f.name}}</b><div><button @click="cart.change(f.id,-1)" :disabled="busy">−</button> {{f.quantity}} <button @click="cart.change(f.id,1)" :disabled="busy">+</button></div><b>{{money(f.price*f.quantity)}}</b></div><div class="line"><b>Total</b><b>{{money(cart.total)}}</b></div><p>Cash on delivery (demo)</p><button class="primary" :disabled="busy" @click="place">{{auth.me?'Place order':'Sign in to order'}}</button></div><p v-else>Your cart is empty. <RouterLink to="/">Browse menu</RouterLink></p></template>
